using System;
class AidChecks {
 static void Check(bool v,string name){if(!v)throw new Exception(name);}
 static void Main(){var classes=new PlayerClasses();var levels=new string[12];for(int i=0;i<12;i++)levels[i]="0";levels[0]="6";Check(classes.TryApply(levels,0),"class setup");var c=new CombatState();c.UpdatePlayerMaxHp(10,classes);c.ApplyPlayerDamage(20);c.SetAidBonus(true,5);Check(c.PlayerHp==25&&c.PlayerMaxHp==45,"aid is not full healing");c.HealPlayer(5);c.SetAidBonus(true,0);Check(c.PlayerHp==25&&c.PlayerMaxHp==40,"expiration subtracts gained current hp");c.SetAidBonus(true,5);int hp=c.PlayerHp;c.SetAidBonus(true,5);Check(c.PlayerHp==hp,"repeated aid does not stack or heal repeatedly");c.ApplyPlayerDamage(c.PlayerHp-3);c.GrantPlayerTemporaryHp(10);c.SetAidBonus(true,0);Check(c.PlayerHp==0&&!c.PlayerDead&&c.DeathFailures==0&&c.PlayerTemporaryHp==10,"expiry can down without damage or temp hp absorption");c.ResetBattle();c.BlockHealing(true);c.SetAidBonus(true,5);Check(c.PlayerHp==40&&c.PlayerMaxHp==45,"healing blockade prevents hp regain but not max increase");c.ClearShortDurationEffects();c.SetAidBonus(true,10);Check(c.PlayerHp==45,"stronger aid adds only delta");c.SetAidBonus(true,5);Check(c.PlayerHp==40,"expiry removes only credited upper layers");c.SetAidBonus(true,0);Check(c.PlayerHp==40,"no deduction for a blocked gain");c.ResetBattle();c.SetAidBonus(true,5);c.BlockHealing(true);c.SetAidBonus(true,10);c.SetAidBonus(true,5);Check(c.PlayerHp==45,"blocked higher layers cannot remove lower-layer credits");c.SetAidBonus(true,0);Check(c.PlayerHp==40,"original lower layer expires normally");var ledger=new AidEffects();ledger.Add(true,3,0);ledger.Add(true,2,10);Check(ledger.ActiveBonus(true,4799)==10&&ledger.ActiveBonus(true,4800)==5&&ledger.ActiveBonus(true,4810)==0,"stronger and weaker overlap lifetimes");c.ResetBattle();c.GrantMonsterTemporaryHp(120);c.GrantMonsterTemporaryHp(20);c.ApplyDamage(100);Check(c.Hp==1000&&c.MonsterTemporaryHp==20,"monster temporary hp absorb without stacking");c.KillMonster();Check(c.Hp==0&&c.MonsterTemporaryHp==0,"instant death bypasses temporary hp");Check(DirectSpell.Find("Mass Healing Word").DiceCount(1,3)==2&&DirectSpell.Find("Mass Healing Word").DiceCount(20,9)==8,"mass healing word scaling");Console.WriteLine("PASS: Aid gain/expiry, overlap, healing blockade layers, downing, reset, monster temporary HP, instant death and mass-healing scaling");}
}
